            return new Object[]{null};
        case 1: // empty outer array
            testArray = new int[0][];
            return new Object[]{testArray};
        case 2: // single empty inner array
            testArray = new int[1][0];
            return new Object[]{testArray};
        case 3: // multiple empty inner arrays
            int rows = random.nextInt(3) + 2; // 2 to 4
            testArray = new int[rows][0];
            return new Object[]{testArray};
        case 4: // single row, single element
