public static Object[] generateValidInput(Random random) {
    int l, r;
    // Generate various cases for l and r
    int caseType = random.nextInt(6);
    switch (caseType) {
        case 0: // Normal case
            l = 1 + random.nextInt(100);
            r = l + 1 + random.nextInt(100);
            break;
        case 1: // l = r
            l = 1 + random.nextInt(100);
            r = l;
            break;
        case 2: // r - l = 1 (minimal range)
            l = 1 + random.nextInt(100);
            r = l + 1;
            break;
        case 3: // Boundary values including 0 and 1
            l = random.nextInt(2); // 0 or 1
            r = l + 1 + random.nextInt(10);
            break;
        case 4: // Large values
            l = 1 + random.nextInt(1000);
            r = l + 1 + random.nextInt(1000);
            break;
        default: // Negative or zero range (edge case)
            l = random.nextInt(10) - 5; // -5 to 4
            r = l + random.nextInt(5) - 2; // may be < l
            break;
    }
    return new Object[]{l, r};
}

