public static Object[] generateValidInput(Random random) {
    // Decide array type: null, empty, or various lengths
    int choice = random.nextInt(10);
    int[] arr;
    if (choice == 0) {
        // null case
        arr = null;
    } else if (choice == 1) {
        // empty array
        arr = new int[0];
    } else if (choice == 2) {
        // single element with boundary value
        int[] boundaryValues = {0, 1, -1, Integer.MAX_VALUE, Integer.MIN_VALUE};
        arr = new int[]{boundaryValues[random.nextInt(boundaryValues.length)]};
    } else if (choice == 3) {
        // multiple elements including boundary values
        int len = random.nextInt(5) + 2; // 2 to 6
        arr = new int[len];
        // First element set to a boundary value
        int[] boundaryValues = {0, 1, -1, Integer.MAX_VALUE, Integer.MIN_VALUE};
        arr[0] = boundaryValues[random.nextInt(boundaryValues.length)];
        // Fill rest with random values
        for (int i = 1; i < len; i++) {
            arr[i] = random.nextInt();
        }
    } else {
        // normal random array
        int len = random.nextInt(10) + 1; // 1 to 10
        arr = new int[len];
        for (int i = 0; i < len; i++) {
            arr[i] = random.nextInt();
        }
    }
    return new Object[]{arr};
}

