    int testCaseType = random.nextInt(10);

    if (testCaseType == 0) {
        // Empty array
        return new Object[]{new int[]{}, 0};
    } else if (testCaseType == 1) {
        // Single element
        int[] arr = new int[]{random.nextInt(2001) - 1000};
        return new Object[]{arr, 1};
    } else if (testCaseType == 2) {
        // Two elements with boundary values
        int val1 = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
        int val2 = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
        return new Object[]{new int[]{val1, val2}, 2};
    } else if (testCaseType == 3) {
        // All zeros
        int size = random.nextInt(10) + 1;
        int[] arr = new int[size];
        return new Object[]{arr, size};
    } else if (testCaseType == 4) {
        // All ones
        int size = random.nextInt(10) + 1;
        int[] arr = new int[size];
        Arrays.fill(arr, 1);
        return new Object[]{arr, size};
    } else if (testCaseType == 5) {
        // All same value
        int val = random.nextInt(2001) - 1000;
        int size = random.nextInt(10) + 1;
        int[] arr = new int[size];
        Arrays.fill(arr, val);
        return new Object[]{arr, size};
    } else if (testCaseType == 6) {
        // Small array with mixed values
        int size = random.nextInt(5) + 1;
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = random.nextInt(21) - 10;
        }
        return new Object[]{arr, size};
    } else if (testCaseType == 7) {
        // Array with extreme values
        int size = random.nextInt(8) + 2;
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
