        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = powers[random.nextInt(powers.length)];
        }
        return new Object[]{arr, size};
    } else {
        // Large random array
        int size = random.nextInt(15) + 1;
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = random.nextInt(2000001) - 1000000;
        }
        return new Object[]{arr, size};
    }
}

