    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            int type = random.nextInt(4);
            if (type == 0) {
                array[i][j] = "value" + random.nextInt(1000);
            } else if (type == 1) {
                array[i][j] = random.nextInt(1000);
            } else if (type == 2) {
                array[i][j] = random.nextDouble();
            } else {
                array[i][j] = random.nextBoolean();
            }
        }
    }

    int n;
    if (rows == 0) {
        n = random.nextBoolean() ? 0 : Integer.MIN_VALUE;
    } else {
        int mode = random.nextInt(8);
        switch (mode) {
            case 0:
                n = 0;
                break;
            case 1:
                n = 1;
                break;
            case 2:
                n = cols - 1;
                break;
            case 3:
                n = -1;
                break;
            case 4:
                n = cols;
                break;
            case 5:
                n = Integer.MAX_VALUE;
                break;
            case 6:
                n = Integer.MIN_VALUE;
                break;
            default:
                n = random.nextInt(cols);
                break;
        }
    }

    if (random.nextInt(10) == 0) {
        array = null;
    }

    return new Object[]{array, n};
}

