public static Object[] generateValidInput(Random random) {
    // Choose a random matrix size between 1 and 10
    int n = random.nextInt(10) + 1;

    // Occasionally test with size 1 (minimal case)
    if (random.nextDouble() < 0.1) {
        n = 1;
    }

    // Generate the cost matrix
    int[][] cost = new int[n][n];

    // Fill with random values, including edge cases
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            // Randomly choose from various value ranges
            int choice = random.nextInt(5);
            switch (choice) {
                case 0:
                    cost[i][j] = 0;
                    break;
                case 1:
                    cost[i][j] = 1;
                    break;
                case 2:
                    cost[i][j] = random.nextInt(100); // small positive
                    break;
                case 3:
                    cost[i][j] = random.nextInt(1000) + 100; // medium positive
                    break;
                case 4:
                    cost[i][j] = random.nextInt(10000) + 1000; // larger positive
                    break;
            }
        }
    }

    // Occasionally set specific boundary values
    if (random.nextDouble() < 0.1 && n > 0) {
        cost[0][0] = Integer.MAX_VALUE;
    }
    if (random.nextDouble() < 0.1 && n > 0) {
        cost[n-1][n-1] = Integer.MIN_VALUE;
    }

    // Return the parameters
    return new Object[]{cost, n};
}

