                    tupleStr[i][j] = String.valueOf(random.nextInt(201) - 100);
                    break;
                default:
                    // Random larger number
                    tupleStr[i][j] = String.valueOf(random.nextInt(2000000) - 1000000);
                    break;
            }
        }
    }

    // Occasionally include null as single-element array or null inner arrays
    if (rows > 0 && random.nextBoolean()) {
        int nullRow = random.nextInt(rows);
