        "a_b_c_d_e_f_g_h",
        "very_long_snake_case_string_to_test",
        "UPPER_CASE",
        "MiXeD_CaSe",
        "123_456",
        "_",
        "__",
        "abc_",
        "_abc",
        "a_",
        "_a",
        "a__",
        "__a",
        "a_b_c_d_e_f_g_h_i_j_k_l_m_n_o_p",
        "test_case_1",
        "testcase",
        "snake2camel",
        "camelCase",
        "PascalCase",
        "kebab-case",
        "space case",
        "tab\tcase",
        "new\nline",
        "unicode_ñ",
        "emoji_😀",
        "special_!@#",
        "a_b_c_d_e_f_g_h_i_j_k_l_m_n_o_p_q_r_s_t_u_v_w_x_y_z"
    };

    int index = random.nextInt(possibilities.length);
    String word = possibilities[index];

    // Occasionally generate a random string
    if (random.nextBoolean()) {
        int len = random.nextInt(20);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < len; i++) {
            char c;
            if (random.nextBoolean()) {
                c = (char) ('a' + random.nextInt(26));
            } else {
                c = (char) ('A' + random.nextInt(26));
            }
            if (random.nextBoolean() && i > 0) {
                sb.append('_');
            }
            sb.append(c);
        }
        word = sb.toString();
    }

    // Occasionally add random underscores at edges
    if (random.nextBoolean()) {
        word = "_" + word;
    }
    if (random.nextBoolean()) {
        word = word + "_";
    }

    return new Object[]{word};
}

