import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class ListifyArray {

    public static String[][] listifyList(String[] list1) {
        String[][] list2 = new String[list1.length][]; // Create a 2D array
        for (int i = 0; i < list1.length; i++) {
            String s = list1[i];
            String[] charArray = s.split(""); // Split string into characters
            list2[i] = charArray; // Assign the character array to the 2D array
        }
        return list2; // Return the 2D array
    }
}

