public static Object[] generateValidInput(Random random) {
    int n;
    int[] arr;

    int caseType = random.nextInt(5);
    switch (caseType) {
        case 0: // Single element
            n = 1;
            arr = new int[]{random.nextInt(200) - 100};
            break;
        case 1: // Two elements
            n = 2;
            arr = new int[]{random.nextInt(200) - 100, random.nextInt(200) - 100};
            break;
        case 2: // Strictly increasing
            n = random.nextInt(10) + 1;
            arr = new int[n];
            int val = random.nextInt(50) - 100;
            for (int i = 0; i < n; i++) {
                arr[i] = val + i * (random.nextInt(5) + 1);
            }
            break;
        case 3: // Strictly decreasing
            n = random.nextInt(10) + 1;
            arr = new int[n];
            val = random.nextInt(50) + 50;
            for (int i = 0; i < n; i++) {
                arr[i] = val - i * (random.nextInt(5) + 1);
            }
            break;
        default: // Random with possible peak
            n = random.nextInt(10) + 1;
            arr = new int[n];
            int peakIndex = random.nextInt(n);
            // Generate left side increasing
            for (int i = 0; i < peakIndex; i++) {
                arr[i] = random.nextInt(100);
            }
            arr[peakIndex] = random.nextInt(100) + 100; // Peak value
            // Generate right side decreasing
            for (int i = peakIndex + 1; i < n; i++) {
                arr[i] = arr[i - 1] - (random.nextInt(10) + 1);
            }
            break;
    }

    // Occasionally use extreme values
    if (random.nextBoolean()) {
        arr[random.nextInt(n)] = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
    }

    return new Object[]{arr, n};
}

