            int len = random.nextInt(20) + 1;
            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = random.nextInt();
            }
            if (caseType == 4) {
                n = random.nextInt(len) + 1;
            } else if (caseType == 5) {
                n = len;
            } else if (caseType == 6) {
                n = len + 1;
            } else {
                n = -1;
