        case 7:
            arr = new int[]{42};
            n = Integer.MAX_VALUE;
            break;
        case 8:
            arr = new int[]{};
            n = Integer.MIN_VALUE;
            break;
        default:
            arr = new int[]{1, 2, 3};
            n = 2;
            break;
    }
    return new Object[]{arr, n};
}

