            str2 = generateRandomString(random, random.nextInt(8) + 1);
            if (str1.length() == str2.length()) {
                str2 += "a";
            }
            break;
        case 4: // same length but not permutations (guarantee false)
            str1 = generateRandomString(random, random.nextInt(8) + 1);
            str2 = generateRandomString(random, str1.length());
            // Ensure at least one character difference
            if (str1.equals(str2)) {
