public static List<Object> findAdverbPosition(String text) {
        List<Object> res = new ArrayList<>();
        int i = 0;
        while (i < text.length()) {
            int j = text.length() - 1;
            while (j >= 0) {
                if (text.substring(i, j).matches("\\w+ly")) {
                    res.add(i);
                    res.add(j);
                    res.add(text.substring(i, j));
                    return res;
                }
                j--;
            }
            i++;
        }
        return res;
    }

