public static Object[] generateValidInput(Random random) {
    int[] array;
    int type = random.nextInt(6);

    switch (type) {
        case 0:
            array = new int[]{};
            break;
        case 1:
            array = new int[]{Integer.MIN_VALUE, -1, 0, 1, Integer.MAX_VALUE};
            break;
        case 2:
            array = new int[]{-1, -2, -3};
            break;
        case 3:
            array = new int[]{1, 2, 3};
            break;
        case 4:
            array = new int[]{0, 0, 0};
            break;
        default:
            int length = random.nextInt(12);
            array = new int[length];
            for (int i = 0; i < length; i++) {
                int selector = random.nextInt(6);
                if (selector == 0) {
                    array[i] = Integer.MIN_VALUE;
                } else if (selector == 1) {
                    array[i] = Integer.MAX_VALUE;
                } else if (selector == 2) {
                    array[i] = -1;
                } else if (selector == 3) {
                    array[i] = 1;
                } else if (selector == 4) {
                    array[i] = 0;
                } else {
                    array[i] = random.nextInt(21) - 10;
                }
            }
            break;
    }

    return new Object[]{array};
}

