import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class ExtractFreq {

    public static int extractFreq(int[][] testArray) {
        HashSet<Integer> count = new HashSet<>();

        for (int i = 0; i < testArray.length; i++) {
            int sum = 0;
            for (int j = 0; j < testArray[i].length; j++) {
                sum += testArray[i][j];
            }
            count.add(sum);
        }
        return count.size();
    }
}

