            }
            // Ensure at least one occurrence
            a[random.nextInt(rlen)] = x;
            break;
        case 6:
            // Array with random values, target may or may not be present
            int nlen = random.nextInt(10);
            a = new int[nlen];
            for (int i = 0; i < nlen; i++) {
                a[i] = random.nextInt(21) - 10;
            }
            x = random.nextInt(21) - 10;
            break;
        case 7:
            // Large array with random values
            int llen = random.nextInt(100) + 50;
            a = new int[llen];
            for (int i = 0; i < llen; i++) {
                a[i] = random.nextInt(21) - 10;
            }
            x = random.nextInt(21) - 10;
