public static Object[] generateValidInput(Random random) {
    // Generate array length between 1 and 15
    int length = 1 + random.nextInt(15);
    int[] nums = new int[length];
    for (int i = 0; i < length; i++) {
        // Generate values in a reasonable range including negatives and positives
        nums[i] = random.nextInt(21) - 10; // -10 to 10
    }

    // Generate valid m and n such that 0 <= m <= n < length
    int m = random.nextInt(length);
    int n = m + random.nextInt(length - m);

    // Occasionally test boundary cases
    int choice = random.nextInt(5);
    if (choice == 0) {
        // Test with m = 0 and n = length - 1 (full range)
        m = 0;
        n = length - 1;
    } else if (choice == 1 && length > 1) {
        // Test with m = 0 and n = 0 (single element at start)
        m = 0;
        n = 0;
    } else if (choice == 2 && length > 1) {
        // Test with m = length - 1 and n = length - 1 (single element at end)
        m = length - 1;
        n = length - 1;
    } else if (choice == 3 && length > 2) {
        // Test with m = 1 and n = length - 2 (middle range)
        m = 1;
        n = length - 2;
    }

    // Occasionally test with large values
    if (random.nextBoolean()) {
        for (int i = 0; i < length; i++) {
            nums[i] = random.nextInt(2001) - 1000; // -1000 to 1000
        }
    }

    // Occasionally test with zeros
    if (random.nextInt(4) == 0) {
        for (int i = 0; i < length; i++) {
            nums[i] = 0;
        }
    }

    // Occasionally test with all same value
    if (random.nextInt(5) == 0) {
        int val = random.nextInt(21) - 10;
        for (int i = 0; i < length; i++) {
            nums[i] = val;
        }
    }

    // Edge case: length 1
    if (random.nextInt(5) == 0) {
        nums = new int[]{random.nextInt(21) - 10};
        m = 0;
        n = 0;
    }

    // Edge case: length 2
    if (random.nextInt(5) == 0) {
        nums = new int[]{random.nextInt(21) - 10, random.nextInt(21) - 10};
        m = random.nextInt(2);
        n = m + random.nextInt(2 - m);
    }

    // Edge case: include Integer.MAX_VALUE and Integer.MIN_VALUE
    if (random.nextInt(10) == 0) {
        nums = new int[]{Integer.MAX_VALUE, Integer.MIN_VALUE, random.nextInt(21) - 10};
        m = 0;
        n = nums.length - 1;
    }

    return new Object[]{nums, m, n};
}

