import java.io.*;
import java.lang.*;
import java.math.*;

class LargestNeg {

    public static int largestNeg(int[] array) {
        int largestNeg = Integer.MIN_VALUE; // Initialize to minimum possible value
        boolean hasNegative = false; // Flag to track if there is any negative number

        for (int i : array) {
            if (i < 0) {
                hasNegative = true; // Found at least one negative number
                if (i > largestNeg) {
                    largestNeg = i; // Update largest negative number found
                }
            }
        }

        return hasNegative ? largestNeg : -1; // Return -1 if no negative numbers found
    }
}

