public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(5);
    int[] a;
    int n;

    switch (choice) {
        case 0:
            // Empty array
            n = 0;
            a = new int[0];
            break;
        case 1:
            // Single element
            n = 1;
            a = new int[]{random.nextInt(20) - 10};
            break;
        case 2:
            // Already sorted (no inversions)
            n = random.nextInt(10) + 1;
            a = new int[n];
            int prev = random.nextInt(5);
            for (int i = 0; i < n; i++) {
                a[i] = prev + random.nextInt(3);
                prev = a[i];
            }
            break;
        case 3:
            // Exactly one inversion
            n = random.nextInt(10) + 2;
            a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = i * 2;
            }
            // Swap two adjacent elements to create one inversion
            int idx = random.nextInt(n - 1);
            int temp = a[idx];
            a[idx] = a[idx + 1];
            a[idx + 1] = temp;
            break;
        default:
            // Random array with mixed values
            n = random.nextInt(10) + 1;
            a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = random.nextInt(20) - 10;
            }
            break;
    }

    return new Object[]{a, n};
}

