full_code:
import java.io.*;
import java.lang.*;
import java.math.*;

class MaxSumArray {

    public static int[] maxSumArray(int[][] arrays) {
        int[] result = new int[0]; // Starting with an empty array
        int maxSum = Integer.MIN_VALUE;

        for (int[] array : arrays) {
            int sum = 0;
            for (int value : array) {
                sum += value;
            }
            if (sum > maxSum) {
                maxSum = sum;
                result = array; // Update result to the current array
            }
        }
        return result;
    }
}

