public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(6);
    int[] array;

    switch (choice) {
        case 0:
            // Empty array
            array = new int[0];
            break;
        case 1:
            // All zeros
            array = new int[random.nextInt(5) + 1];
            break;
        case 2:
            // No zeros
            int length = random.nextInt(10);
            array = new int[length];
            for (int i = 0; i < length; i++) {
                array[i] = random.nextInt(10) + 1;
            }
            break;
        case 3:
            // Mixed with boundary values
            array = new int[]{0, Integer.MAX_VALUE, 0, Integer.MIN_VALUE, 1, -1, 0, 0};
            break;
        case 4:
            // Single element cases
            int singleChoice = random.nextInt(3);
            if (singleChoice == 0) {
                array = new int[]{0};
            } else if (singleChoice == 1) {
                array = new int[]{random.nextInt(10) + 1};
            } else {
                array = new int[]{-random.nextInt(10) - 1};
            }
            break;
        default:
            // Random array with zeros and non-zeros
            int len = random.nextInt(15);
            array = new int[len];
            for (int i = 0; i < len; i++) {
                if (random.nextBoolean()) {
                    array[i] = 0;
                } else {
                    array[i] = random.nextInt(20) - 10;
                }
            }
            break;
    }

    return new Object[]{array};
}

