            String half = generateRandomAlphabeticString(random, random.nextInt(10));
            input = half + new StringBuilder(half).reverse().toString();
            break;
        case 3: // All same characters
            char c = (char)('A' + random.nextInt(26));
            input = String.valueOf(c).repeat(random.nextInt(20));
            break;
        default: // Random string
            input = sb.toString();
            break;
    }

    return new Object[]{input};
}

private static String generateRandomAlphabeticString(Random random, int length) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < length; i++) {
        sb.append((char)('A' + random.nextInt(26)));
    }
    return sb.toString();
}

