public static Object[] generateValidInput(Random random) {
    // Generate random strings with lowercase letters
    int maxLength = 10;
    int m = random.nextInt(maxLength + 1);
    int n = random.nextInt(maxLength + 1);
    int o = random.nextInt(maxLength + 1);

    StringBuilder x = new StringBuilder();
    StringBuilder y = new StringBuilder();
    StringBuilder z = new StringBuilder();

    for (int i = 0; i < m; i++) {
        x.append((char) ('a' + random.nextInt(26)));
    }
    for (int i = 0; i < n; i++) {
        y.append((char) ('a' + random.nextInt(26)));
    }
    for (int i = 0; i < o; i++) {
        z.append((char) ('a' + random.nextInt(26)));
    }

    // Occasionally create identical strings to test full match
    if (random.nextBoolean()) {
        String common = "abc";
        x = new StringBuilder(common);
        y = new StringBuilder(common);
        z = new StringBuilder(common);
        m = common.length();
        n = common.length();
        o = common.length();
    }

    // Occasionally test with empty strings
    if (random.nextInt(10) == 0) {
        m = 0;
        x = new StringBuilder();
    }
    if (random.nextInt(10) == 0) {
        n = 0;
        y = new StringBuilder();
    }
    if (random.nextInt(10) == 0) {
        o = 0;
        z = new StringBuilder();
    }

    // Occasionally test with single character strings
    if (random.nextInt(10) == 0 && m > 0) {
        m = 1;
        x = new StringBuilder("a");
    }

    return new Object[]{x.toString(), y.toString(), z.toString(), m, n, o};
}

