        case 3: // both arrays with overlapping elements
            int size = 1 + random.nextInt(3);
            arr1 = generateRandomArray(random, size);
            arr2 = new int[size];
            // copy some elements from arr1 to arr2 to create overlap
            for (int i = 0; i < size; i++) {
                if (random.nextBoolean()) {
                    arr2[i] = arr1[i];
                } else {
                    arr2[i] = random.nextInt();
                }
            }
            break;
        case 4: // both arrays with no overlap
            arr1 = generateRandomArray(random, 1 + random.nextInt(3));
            arr2 = new int[arr1.length];
            // ensure elements are different from arr1
