full_code:
import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class FrequencyOfLargest {

    public static int frequencyOfLargest(int n, int[] arr) {
        int max = Integer.MIN_VALUE; // Initialize max to the smallest possible integer
        int maxCount = 0;

        for (int i = 0; i < n; i++) {
            if (arr[i] > max) {
                max = arr[i];
                maxCount = 1; // Reset count for new max
            } else if (arr[i] == max) {
                maxCount++;
            }
        }
        return maxCount;
    }
}

