public static Object[] generateValidInput(Random random) {
    // Decide which kind of input to generate
    int choice = random.nextInt(10);

    int n;
    int[] arr;

    switch (choice) {
        case 0: // n = 0 (empty segment)
            arr = new int[random.nextInt(5) + 1];
            n = 0;
            break;
        case 1: // n = 1, single element array
            arr = new int[1];
            arr[0] = random.nextInt(200) - 100;
            n = 1;
            break;
        case 2: // all elements equal
            int len = random.nextInt(10) + 2;
            arr = new int[len];
            int val = random.nextInt(200) - 100;
            Arrays.fill(arr, val);
            n = len;
            break;
        case 3: // strictly increasing
            len = random.nextInt(10) + 2;
            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = random.nextInt(200) - 100 + i;
            }
            n = len;
            break;
        case 4: // strictly decreasing
            len = random.nextInt(10) + 2;
            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = random.nextInt(200) - 100 - i;
            }
            n = len;
            break;
        case 5: // largest value at beginning
            len = random.nextInt(10) + 3;
            arr = new int[len];
            arr[0] = 100 + random.nextInt(100);
            for (int i = 1; i < len; i++) {
                arr[i] = random.nextInt(100) - 50;
            }
            n = len;
            break;
        case 6: // largest value at end
            len = random.nextInt(10) + 3;
            arr = new int[len];
            for (int i = 0; i < len - 1; i++) {
                arr[i] = random.nextInt(100) - 50;
            }
            arr[len - 1] = 100 + random.nextInt(100);
            n = len;
            break;
        case 7: // multiple occurrences of largest
            len = random.nextInt(8) + 5;
            arr = new int[len];
            int maxVal = 50 + random.nextInt(100);
            int maxCount = random.nextInt(len - 2) + 2; // at least 2 occurrences
            // place maxVal at random positions
            for (int i = 0; i < maxCount; i++) {
                int pos = random.nextInt(len);
                while (arr[pos] != 0) { // non-zero default, but we use 0 as placeholder
                    pos = random.nextInt(len);
                }
                arr[pos] = maxVal;
            }
            // fill rest with smaller values
            for (int i = 0; i < len; i++) {
                if (arr[i] == 0) {
                    arr[i] = random.nextInt(maxVal);
                }
            }
            n = len;
            break;
        case 8: // n less than array length
            len = random.nextInt(10) + 5;
            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = random.nextInt(200) - 100;
            }
            n = random.nextInt(len) + 1; // 1 to len
            break;
        case 9: // extreme values: Integer.MAX_VALUE, MIN_VALUE
            len = random.nextInt(5) + 2;
            arr = new int[len];
            int idxMax = random.nextInt(len);
            int idxMin = random.nextInt(len);
            for (int i = 0; i < len; i++) {
                if (i == idxMax) {
                    arr[i] = Integer.MAX_VALUE;
                } else if (i == idxMin) {
                    arr[i] = Integer.MIN_VALUE;
                } else {
                    arr[i] = random.nextInt();
                }
            }
            n = len;
            break;
        default:
            // fallback: random array
            len = random.nextInt(10) + 1;
            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = random.nextInt(200) - 100;
            }
            n = len;
    }

    return new Object[]{n, arr};
}

