    // Generate random length between 1 and 10 for the longer array
    int length = random.nextInt(10) + 1;

    // Generate a sorted base array of length-1 elements
    int[] base = new int[length - 1];
    if (length > 1) {
        int prev = random.nextInt(10) - 5;
        for (int i = 0; i < base.length; i++) {
            base[i] = prev;
            prev += random.nextInt(3) + 1;
        }
    }

    // Create arr2 (shorter array) from base
    int[] arr2 = base.clone();

    // Insert an extra element into arr1 at random position
    int insertPos = random.nextInt(length);
    int[] arr1 = new int[length];

    if (length == 1) {
        // Single element case
        arr1[0] = random.nextInt(10);
        arr2 = new int[0];
    } else {
        // Build arr1 with extra element inserted
        int extraValue;
        if (insertPos == 0) {
            extraValue = base[0] - random.nextInt(3) - 1;
        } else if (insertPos == length - 1) {
            extraValue = base[base.length - 1] + random.nextInt(3) + 1;
        } else {
            // Between two elements
            int lower = base[insertPos - 1];
            int upper = base[insertPos];
            int range = upper - lower;
            if (range > 1) {
                extraValue = lower + random.nextInt(range - 1) + 1;
            } else {
                // If no gap, adjust base or use different approach
                extraValue = lower + 1;
                // Ensure array stays sorted by rebuilding
