                    }
                }
                // Check if sorted, if not, regenerate base
                boolean sorted = true;
                for (int i = 1; i < length; i++) {
                    if (temp[i] <= temp[i - 1]) {
                        sorted = false;
                        break;
                    }
                }
                if (!sorted) {
                    // Simple fallback: generate new sorted arrays
                    int[] newBase = new int[length - 1];
