                    for (int i = 0; i < length; i++) {
                        if (i < newPos) {
                            arr1[i] = newBase[i];
                        } else if (i == newPos) {
                            arr1[i] = newBase[Math.min(newPos, newBase.length - 1)] + random.nextInt(3) + 1;
                        } else {
                            arr1[i] = newBase[i - 1];
                        }
                    }
