public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(7);

    if (choice == 0) {
        // Empty array, n=0: covers no iterations and minFrequency reset to 0
        return new Object[]{new int[0], 0};

    } else if (choice == 1) {
        // n=0 but non-empty array: elements after n are ignored
        int len = random.nextInt(5) + 1;
        int[] arr = new int[len];
        for (int i = 0; i < len; i++) {
            arr[i] = random.nextInt(101);
        }
        return new Object[]{arr, 0};

    } else if (choice == 2) {
        // Single element, n=1, boundary values 0 and 100
        int[] arr = new int[1];
        arr[0] = random.nextBoolean() ? 0 : 100;
        return new Object[]{arr, 1};

    } else if (choice == 3) {
        // All elements equal -> max frequency == min frequency -> diff = 0
        int len = random.nextInt(20) + 1;
        int value = random.nextInt(101);
        int[] arr = new int[len];
        for (int i = 0; i < len; i++) {
            arr[i] = value;
        }
        return new Object[]{arr, len};

    } else if (choice == 4) {
        // Two distinct frequencies: one element appears once, another appears multiple times
        int len = 2 + random.nextInt(10);
        int[] arr = new int[len];
        int uniqueVal = random.nextInt(101);
        int repeatedVal = random.nextInt(101);
        while (repeatedVal == uniqueVal) {
            repeatedVal = random.nextInt(101);
        }
        arr[0] = uniqueVal;
        for (int i = 1; i < len; i++) {
            arr[i] = repeatedVal;
        }
        return new Object[]{arr, len};

    } else if (choice == 5) {
        // Multiple distinct frequencies with random values
        int len = random.nextInt(30) + 1;
        int[] arr = new int[len];
        for (int i = 0; i < len; i++) {
            arr[i] = random.nextInt(101);
        }
        // Randomly choose n between 0 and len (inclusive) to test partial processing
        int n = random.nextInt(len + 1);
        return new Object[]{arr, n};

    } else {
        // Large array with many repeated values to stress max/min differences
        int len = random.nextInt(50) + 1;
        int[] arr = new int[len];
        // Bias toward a few values to create high frequency differences
        int distinctCount = 1 + random.nextInt(5);
        for (int i = 0; i < len; i++) {
            arr[i] = random.nextInt(distinctCount);
        }
        return new Object[]{arr, len};
    }
}

