import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class CountHexadecimal {

    public static int countHexadecimal(int l, int r) {
        int c = 0;
        for (int i = l; i <= r; i++) {
            String str = Integer.toHexString(i);
            int num = str.length();
            for (int j = 0; j < num; j++) {
                char ch = str.charAt(j);
                if (ch >= 'A' && ch <= 'F') {
                    c++;
                } else if (ch >= 'a' && ch <= 'f') {
                    c++;
                }
            }
        }
        return c;
    }
}

