import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class ReverseArrayLists {

    public static int[][] reverseListLists(int[][] lists) {
        int[][] result = new int[lists.length][]; // Initialize result array

        for (int i = 0; i < lists.length; i++) {
            int[] list = lists[i];
            result[i] = new int[list.length]; // Create a new array for the reversed list
            for (int j = 0; j < list.length; j++) {
                result[i][j] = list[list.length - 1 - j]; // Reverse the elements
            }
        }

        return result;
    }
}

