public static Object[] generateValidInput(Random random) {
    int[] edgeCases = {
        0, 1, -1, 2, 5, 9,
        10, 11, 12, 14, 19, 22, 28, 34, 47, 61, 75, 99,
        197, 2208, 289, 4414,
        Integer.MIN_VALUE,
        -100, -999, 100, 1000, 5000, 99999,
        1000000, 5000000, 9999999
    };

    int choice = random.nextInt(10);
    int x;
    if (choice < 4) {
        x = edgeCases[random.nextInt(edgeCases.length)];
    } else if (choice < 7) {
        x = random.nextInt(100000);
    } else if (choice < 9) {
        x = random.nextInt(10000000);
    } else {
