public static Object[] generateValidInput(Random random) {
    String[][] cases = {
        {"", ""},           // both empty
        {"a", "a"},         // single same char
        {"a", "b"},         // single different char
        {"ab", "ba"},       // isomorphic
        {"ab", "aa"},       // not isomorphic
        {"paper", "title"}, // isomorphic
        {"foo", "bar"},     // not isomorphic
        {"egg", "add"},     // isomorphic
        {"abc", "def"},     // isomorphic
        {"aa", "ab"},       // not isomorphic
        {"ab", "ca"},       // not isomorphic
        {"abcabc", "xyzxyz"} // isomorphic
    };

    int index = random.nextInt(cases.length);
    String str1 = cases[index][0];
    String str2 = cases[index][1];

    // Occasionally add random strings
    if (random.nextBoolean()) {
        int len1 = random.nextInt(5);
        int len2 = random.nextInt(5);
        StringBuilder sb1 = new StringBuilder();
        StringBuilder sb2 = new StringBuilder();
        for (int i = 0; i < len1; i++) {
            sb1.append((char)('a' + random.nextInt(26)));
        }
        for (int i = 0; i < len2; i++) {
            sb2.append((char)('a' + random.nextInt(26)));
        }
        str1 = sb1.toString();
        str2 = sb2.toString();
    }

    // Occasionally test null (though method may throw NPE, but for coverage)
    if (random.nextInt(10) == 0) {
        str1 = null;
    }
    if (random.nextInt(10) == 0) {
        str2 = null;
    }

    return new Object[]{str1, str2};
}

