public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(8);

    if (choice == 0) {
        return new Object[]{new int[0], 0, -1};
    }

    int len = random.nextInt(8) + 1;

    if (choice == 1) {
        int[] a = new int[len];
        for (int i = 0; i < len; i++) a[i] = i;
        return new Object[]{a, 0, len - 1};
    }

    if (choice == 2) {
        int[] a = new int[len];
        int offset = random.nextInt(len + 1) + 1;
        for (int i = 0; i < len; i++) a[i] = offset + i;
        return new Object[]{a, 0, len - 1};
    }

    if (choice == 3) {
        int[] a = new int[len];
        int missing = random.nextInt(len) + 1;
        for (int i = 0; i < missing; i++) a[i] = i;
        for (int i = missing; i < len; i++) a[i] = i + 1;
        return new Object[]{a, 0, len - 1};
    }

    if (choice == 4) {
        int[] a = new int[len];
        int val = random.nextInt(10) - 5;
        for (int i = 0; i < len; i++) {
            a[i] = val;
            val += random.nextInt(3);
        }
        int start = random.nextInt(len);
        int end = random.nextInt(len - start) + start;
        return new Object[]{a, start, end};
    }

    if (choice == 5) {
        int val = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
        return new Object[]{new int[]{val}, 0, 0};
    }

    if (choice == 6) {
        int[] a = new int[len];
        if (random.nextBoolean()) {
            for (int i = 0; i < len; i++) a[i] = 0;
        } else {
            for (int i = 0; i < len; i++) {
                if (i < len / 2) a[i] = 0;
                else a[i] = i;
            }
        }
        int start = random.nextInt(len);
        int end = random.nextInt(len - start) + start;
        return new Object[]{a, start, end};
    }

    int[] a = new int[len];
    for (int i = 0; i < len; i++) a[i] = i;
    int pos = random.nextInt(len);
    return new Object[]{a, pos, pos - 1};
}

