        "a",
        "A",
        "PythonProgramLanguage",
        "PythonProgram",
        "ProgrammingLanguage",
        "ABCdef",
        "aBcDeF",
        "ALLUPPER",
        "alllower",
        "A",
        "a",
        "AB",
        "Ab",
        "aB",
