        "AAA",
        "aaa",
        "AaA",
        "aAa",
        "AAa",
        "aAA",
        "A a", // space, but regex will treat as non-uppercase
        "ABcdEFgh",
        "xYz",
        "Z",
        "z"
    };

    // Randomly choose between predefined and random generation
    int choice = random.nextInt(10);
    if (choice < 8 && edgeCases.length > 0) {
        // Pick a predefined edge case
        String input = edgeCases[random.nextInt(edgeCases.length)];
        return new Object[]{input};
    } else {
        // Generate a random string with varying uppercase patterns
        int len = random.nextInt(20) + 1; // 1 to 20
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < len; i++) {
            // Randomly decide uppercase or lowercase
            boolean upper = random.nextBoolean();
            if (upper) {
                sb.append((char) ('A' + random.nextInt(26)));
            } else {
                sb.append((char) ('a' + random.nextInt(26)));
            }
        }
        String input = sb.toString();
        return new Object[]{input};
    }
}

