public static Object[] generateValidInput(Random random) {
    int n;
    int selector = random.nextInt(10);
    switch (selector) {
        case 0:
            n = 0;
            break;
        case 1:
            n = 1;
            break;
        case 2:
            n = -1;
            break;
        case 3:
            n = Integer.MIN_VALUE;
            break;
        case 4:
            // Perfect numbers: sum of proper divisors == n
            int[] perfect = {6, 28, 496, 8128};
            n = perfect[random.nextInt(perfect.length)];
            break;
        case 5:
            // Known abundant numbers
            int[] abundant = {12, 18, 20, 24, 30, 36, 40, 42, 48, 54, 56, 60, 66, 70, 72, 78, 80, 84, 88, 90, 96, 100, 102, 104, 108, 112, 114, 120};
            n = abundant[random.nextInt(abundant.length)];
            break;
        case 6:
            // Known deficient numbers
            int[] deficient = {2, 3, 4, 5, 7, 8, 9, 10, 11, 14, 15, 16, 17, 19, 21, 22, 23, 25, 26, 27, 29, 31, 32, 33, 34, 35, 37, 38, 39, 41, 43, 44, 45, 46, 47, 49, 50};
            n = deficient[random.nextInt(deficient.length)];
            break;
        case 7:
            // Random small positive
            n = random.nextInt(2000) + 1;
            break;
        case 8:
            // Random non-positive
            n = -random.nextInt(1000);
            break;
        default:
            // Random positive within a safe, fast range
            n = random.nextInt(10000) + 1;
            break;
    }
    return new Object[]{n};
}

