    int choice = random.nextInt(4);
    String[][] testArray;
    switch (choice) {
        case 0:
            // Empty array
            testArray = new String[0][0];
            break;
        case 1:
            // Single row with single element
            testArray = new String[][]{{String.valueOf(random.nextFloat() * 100)}};
            break;
        case 2:
            // Single row with multiple elements
            testArray = new String[][]{
                    {String.valueOf(random.nextFloat() * 100), String.valueOf(random.nextFloat() * 100)}
            };
            break;
        case 3:
            // Multiple rows with varying lengths
            int rows = 1 + random.nextInt(5);
            testArray = new String[rows][];
            for (int i = 0; i < rows; i++) {
                int cols = 1 + random.nextInt(3);
                testArray[i] = new String[cols];
                for (int j = 0; j < cols; j++) {
                    // Mix of integer strings, decimal strings, and boundary values
                    int type = random.nextInt(3);
                    switch (type) {
                        case 0:
                            testArray[i][j] = String.valueOf(random.nextInt(200) - 100);
                            break;
                        case 1:
                            testArray[i][j] = String.valueOf(random.nextFloat() * 200 - 100);
                            break;
                        case 2:
                            // Boundary values
                            testArray[i][j] = String.valueOf(random.nextBoolean() ? 0 : 1);
                            break;
                    }
                }
            }
            break;
        default:
            testArray = new String[0][0];
    }
    return new Object[]{testArray};
}

