import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class CheckKElements {

    public static Boolean checkKElements(int[][] testArr, int k) {
        for (int[] arr : testArr) {
            for (int num : arr) {
                if (num != k) {
                    return false; // Return false immediately if an element is not k
                }
            }
        }
        return true; // All elements were k
    }
}

