public static Object[] generateValidInput(Random random) {
    String string;
    String secondString;
    int caseType = random.nextInt(8);

    switch (caseType) {
        case 0: // normal case with random strings
            string = generateRandomString(random, random.nextInt(15) + 1);
            secondString = generateRandomString(random, random.nextInt(15) + 1);
            break;
        case 1: // both empty
            string = "";
            secondString = "";
            break;
        case 2: // empty first string
            string = "";
            secondString = generateRandomString(random, random.nextInt(10) + 1);
            break;
        case 3: // empty second string
            string = generateRandomString(random, random.nextInt(10) + 1);
            secondString = "";
            break;
        case 4: // first string contains all characters from second
            string = generateRandomString(random, random.nextInt(10) + 1);
            secondString = string;
            break;
        case 5: // second string contains all characters from first
            string = generateRandomString(random, random.nextInt(5) + 1);
            secondString = string + generateRandomString(random, random.nextInt(5) + 1);
            break;
        case 6: // single character strings
            string = generateRandomString(random, 1);
            secondString = generateRandomString(random, 1);
            break;
        default: // longer strings with overlapping characters
            string = generateRandomString(random, random.nextInt(20) + 10);
            secondString = generateRandomString(random, random.nextInt(10) + 1);
            break;
    }

    return new Object[]{string, secondString};
}

private static String generateRandomString(Random random, int length) {
    String chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < length; i++) {
        sb.append(chars.charAt(random.nextInt(chars.length())));
    }
    return sb.toString();
}

