public static Object[] generateValidInput(Random random) {
    int rows = 1 + random.nextInt(10); // 1 to 10 rows
    Object[][] testArray = new Object[rows][2];
    int minValue = Integer.MAX_VALUE;
    int minRowIndex = 0;
    for (int i = 0; i < rows; i++) {
        // Generate a name string (non-empty, could include random characters)
        int nameLength = 1 + random.nextInt(10);
        StringBuilder sb = new StringBuilder();
        for (int j = 0; j < nameLength; j++) {
            char c = (char) ('a' + random.nextInt(26));
            sb.append(c);
        }
        // Generate an integer value, sometimes boundary values
        int value;
        int choice = random.nextInt(5);
        switch (choice) {
            case 0: value = Integer.MAX_VALUE; break;
            case 1: value = Integer.MIN_VALUE; break;
            case 2: value = 0; break;
            case 3: value = 1 + random.nextInt(1000); break;
            default: value = -1 - random.nextInt(1000); break;
        }
        testArray[i][0] = sb.toString();
        testArray[i][1] = value;
        // Track the minimum value for potential tie-breaking (but method returns first min)
        if (value < minValue) {
            minValue = value;
            minRowIndex = i;
        }
    }
    // Sometimes add a row with the minimum value at the end to test tie-breaking
    if (random.nextBoolean() && rows > 0) {
        // Ensure at least one row, modify last row to have the same min value
        testArray[rows-1][1] = minValue;
    }
    // Occasionally return an empty array
    if (random.nextInt(10) == 0) {
        testArray = new Object[0][2];
    }
    return new Object[]{testArray};
}

