public static Object[] generateValidInput(Random random) {
    int rows = 1 + random.nextInt(5);      // 1..5, avoids empty row dimension
    int cols = random.nextInt(4);          // 0..3, includes empty column case

    int[][] testTup1 = new int[rows][cols];
    int[][] testTup2 = new int[rows][cols];

    int[] specials = {0, 1, -1, Integer.MAX_VALUE, Integer.MIN_VALUE};

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            testTup1[i][j] = random.nextBoolean()
                    ? specials[random.nextInt(specials.length)]
                    : random.nextInt();
            testTup2[i][j] = random.nextBoolean()
                    ? specials[random.nextInt(specials.length)]
                    : random.nextInt();
        }
    }

    // When cols == 0, testTup2 is never accessed, so null is a valid boundary case.
    if (cols == 0 && random.nextBoolean()) {
        testTup2 = null;
    }

    return new Object[]{testTup1, testTup2};
}

