full_code:
import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class BinomialCoeff {

    public static int binomialCoeff(int n, int k) {
        if (k > n - k)
            k = n - k;
        int c = 1;
        for (int i = 1; i <= k; i++) {
            c = c * (n - i + 1) / i;
        }
        return c;
    }
}

