    // Predefined test cases covering various scenarios
    Object[][] predefinedCases = {
        // Normal valid cases
        new Object[]{5, 2},
        new Object[]{4, 3},
        new Object[]{3, 2},
        new Object[]{10, 5},
        new Object[]{10, 0},
        new Object[]{10, 10},
        new Object[]{10, 1},
        new Object[]{0, 0},
        new Object[]{1, 0},
        new Object[]{1, 1},
        // Boundary values
        new Object[]{0, 1},          // invalid: k > n
        new Object[]{5, -1},         // negative k
        new Object[]{-5, 2},         // negative n
        new Object[]{Integer.MAX_VALUE, 1},
        new Object[]{Integer.MIN_VALUE, 0},
        new Object[]{Integer.MIN_VALUE, 1},
        // Edge cases with potential overflow
        new Object[]{34, 17},        // C(34,17) > Integer.MAX_VALUE
        new Object[]{30, 15},        // large but fits
        // Branch coverage: k > n-k true
        new Object[]{7, 5},          // n=7, k=5 => n-k=2, so k>2 true, set k=2
        // Branch coverage: k <= n-k false
        new Object[]{7, 2}           // n=7, k=2 => n-k=5, condition false
    };

    int choice = random.nextInt(15); // 0-14
    if (choice < predefinedCases.length) {
        return predefinedCases[choice];
    } else {
        // Generate random valid pair with n between 0 and 30
        int n = random.nextInt(31);
        int k = random.nextInt(n + 1);
        // With 20% probability, generate invalid values
        if (random.nextInt(5) == 0) {
            n = random.nextInt(20) - 10; // -10 to 9
            k = random.nextInt(20) - 10; // -10 to 9
        }
        return new Object[]{n, k};
    }
}

