public static Object[] generateValidInput(Random random) {
    int rows = random.nextInt(10); // 0 to 9 rows
    int cols = random.nextInt(10); // 0 to 9 columns

    // Edge case: empty matrix
    if (rows == 0) {
        int[][] emptyMatrix = new int[0][0];
        return new Object[]{emptyMatrix};
    }

    // Ensure columns > 0 for non-empty matrix
    if (cols == 0) {
        cols = 1;
    }

    int[][] matrix = new int[rows][cols];
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            // Generate values including boundary cases
            int type = random.nextInt(5);
            switch (type) {
                case 0:
                    matrix[i][j] = 0;
                    break;
                case 1:
                    matrix[i][j] = 1;
                    break;
                case 2:
                    matrix[i][j] = -1;
                    break;
                case 3:
                    matrix[i][j] = Integer.MAX_VALUE;
                    break;
                case 4:
                    matrix[i][j] = Integer.MIN_VALUE;
                    break;
                default:
                    matrix[i][j] = random.nextInt(2001) - 1000; // -1000 to 1000
            }
        }
    }

    // Occasionally create duplicate rows or rows with same sum to test tie-breaking
    if (rows > 1 && random.nextBoolean()) {
        int targetRow = random.nextInt(rows);
        int copyRow = random.nextInt(rows);
        if (copyRow != targetRow) {
            matrix[copyRow] = matrix[targetRow].clone();
        }
    }

    return new Object[]{matrix};
}

