            }
            break;
        case 1: // Random positive (0..10)
            n = random.nextInt(10) + 2; // at least 2
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = random.nextInt(11);
            }
            break;
        case 2: // Random including negatives (-5..5)
            n = random.nextInt(10) + 2;
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = random.nextInt(11) - 5; // -5 to 5
            }
            break;
        case 3: // n = 1, any value
            n = 1;
            arr = new int[1];
            arr[0] = random.nextInt(20) - 10; // -10 to 9
            break;
        case 4: // n = 2 with specific patterns
            n = 2;
            arr = new int[2];
            arr[0] = random.nextInt(5); // 0..4
            arr[1] = random.nextInt(5);
            // possible outcomes: jump from 0 to 1 if arr[0] >= 1, else unreachable
