public static Object[] generateValidInput(Random random) {
    int[] boundaries = {0, 1, -1, 10, 100, 1000, 1011, 1101101, Integer.MAX_VALUE, Integer.MIN_VALUE, 9, 99, 999999999};
    int choice = random.nextInt(boundaries.length + 2);
    int input;
    if (choice < boundaries.length) {
        input = boundaries[choice];
    } else if (choice == boundaries.length) {
        // Random positive binary-like number (digits only 0 or 1, up to 10 digits)
        input = random.nextInt(1 << 10); // 0 to 1023 in binary representation
    } else {
        // Random number with digits 0-9 (may not be valid binary, but tests robustness)
        input = random.nextInt(Integer.MAX_VALUE);
    }
    return new Object[]{input};
}

