public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(6);
    int[][] input;
    int k;

    switch (choice) {
        case 0:
            // All tuples have same length (normal case)
            k = random.nextInt(5) + 1;
            int rows = random.nextInt(5) + 1;
            input = new int[rows][k];
            for (int i = 0; i < rows; i++) {
                input[i] = new int[k];
                for (int j = 0; j < k; j++) {
                    input[i][j] = random.nextInt();
                }
            }
            break;
        case 1:
            // All tuples have same length with k=0 (empty arrays)
            k = 0;
            rows = random.nextInt(5) + 1;
            input = new int[rows][0];
            break;
        case 2:
            // All tuples have same length with k=1
            k = 1;
            rows = random.nextInt(5) + 1;
            input = new int[rows][1];
            for (int i = 0; i < rows; i++) {
                input[i][0] = random.nextInt();
            }
            break;
        case 3:
            // Not all tuples have same length (mixed lengths)
            k = random.nextInt(5) + 1;
            rows = random.nextInt(5) + 2;
            input = new int[rows][];
            for (int i = 0; i < rows; i++) {
                int length = random.nextInt(6);
                input[i] = new int[length];
                for (int j = 0; j < length; j++) {
                    input[i][j] = random.nextInt();
                }
            }
            // Ensure at least one tuple has different length
            if (input.length > 0) {
                input[0] = new int[k + 1];
            }
            break;
        case 4:
            // Empty input array (input.length == 0)
            k = random.nextInt(5) + 1;
            input = new int[0][];
            break;
        case 5:
            // Single tuple (edge case)
            k = random.nextInt(5) + 1;
            input = new int[1][k];
            for (int j = 0; j < k; j++) {
                input[0][j] = random.nextInt();
            }
            break;
        default:
            // Fallback (should not happen)
            k = 3;
            input = new int[][]{{11, 22, 33}, {44, 55, 66}};
            break;
    }

    return new Object[]{input, k};
}

