    int type = random.nextInt(6);
    int outerLen;
    boolean forceEmpty = false;
    boolean forceNonEmpty = false;

    if (type == 0) {
        outerLen = 0;
    } else if (type == 1) {
        outerLen = 1;
    } else if (type == 2) {
        outerLen = 2;
        forceEmpty = true;
        forceNonEmpty = true;
    } else if (type == 3) {
        outerLen = 2 + random.nextInt(3);
        forceEmpty = true;
        forceNonEmpty = true;
    } else if (type == 4) {
        outerLen = 2 + random.nextInt(3);
    } else {
        outerLen = 1 + random.nextInt(4);
    }

    int[][] input = new int[outerLen][];

    for (int i = 0; i < outerLen; i++) {
        int innerLen;
        if (forceEmpty && i == 0) {
            innerLen = 0;
        } else if (forceNonEmpty && i == 1) {
            innerLen = 1 + random.nextInt(3);
        } else {
            innerLen = random.nextInt(4);
        }

        int[] inner = new int[innerLen];
        for (int j = 0; j < innerLen; j++) {
            int value;
            int valueType = random.nextInt(8);
            if (valueType == 0) {
                value = 0;
            } else if (valueType == 1) {
                value = 1;
            } else if (valueType == 2) {
                value = -1;
            } else if (valueType == 3) {
                value = Integer.MAX_VALUE;
            } else if (valueType == 4) {
                value = Integer.MIN_VALUE;
            } else {
                value = random.nextInt();
            }
            inner[j] = value;
        }
        input[i] = inner;
    }

    return new Object[]{input};
}

