// Helper to generate an integer that is often a boundary value
private static Integer randomBoundaryInt(Random random) {
    int choice = random.nextInt(10);
    switch (choice) {
        case 0: return Integer.MAX_VALUE;
        case 1: return Integer.MIN_VALUE;
        case 2: return -1;
