class Overlapping {

    public static Boolean overlapping(int[] array1, int[] array2) {
        int i = 0;
        int j = 0;

        while (i < array1.length && j < array2.length) {
            if (array1[i] == array2[j]) {
                j++;
                if (j == array2.length) {
                    return true;
                }
            } else {
                j = 0; // reset j to check for next match
            }
            i++;
        }
        return false;
    }
}

