public static Object[] generateValidInput(Random random) {
    // Decide scenario
    int scenario = random.nextInt(10);
    String[] str;
    int l;

    switch (scenario) {
        case 0: // Normal case: array with some strings of length l
        {
            int n = random.nextInt(6) + 1; // 1 to 6 strings
            str = new String[n];
            // Choose a target length that will appear at least once
            int targetLen = random.nextInt(6); // 0 to 5
            // Ensure at least one string of that length
            int pos = random.nextInt(n);
            str[pos] = generateString(random, targetLen);
            // Fill the rest with random lengths (0-10)
            for (int i = 0; i < n; i++) {
                if (i == pos) continue;
                int len = random.nextInt(11); // 0 to 10
                str[i] = generateString(random, len);
            }
            l = targetLen;
            break;
        }
        case 1: // Empty array
        {
            str = new String[0];
            l = random.nextInt(11) - 2; // -2 to 8
            break;
        }
        case 2: // Null array
        {
            str = null;
            l = random.nextInt(11); // 0 to 10
            break;
        }
        case 3: // All strings same length, l matches
        {
            int len = random.nextInt(6); // 0 to 5
            int n = random.nextInt(5) + 1; // 1 to 5
            str = new String[n];
            for (int i = 0; i < n; i++) {
                str[i] = generateString(random, len);
            }
            l = len;
            break;
        }
        case 4: // No string of length l
        {
            int n = random.nextInt(5) + 1; // 1 to 5
            str = new String[n];
            // generate strings of lengths 0..10 (excluding 7)
            for (int i = 0; i < n; i++) {
                int len;
                do {
                    len = random.nextInt(11); // 0 to 10
                } while (len == 7);
                str[i] = generateString(random, len);
            }
            l = 7; // length that does not appear
            break;
        }
        case 5: // l = 0, some empty strings
        {
            int n = random.nextInt(5) + 1; // 1 to 5
            str = new String[n];
            // At least one empty string
            int pos = random.nextInt(n);
            str[pos] = ""; // length 0
            for (int i = 0; i < n; i++) {
                if (i == pos) continue;
                int len = random.nextInt(6) + 1; // 1 to 6
                str[i] = generateString(random, len);
            }
            l = 0;
            break;
        }
        case 6: // l = -1
        {
            int n = random.nextInt(5) + 1; // 1 to 5
            str = new String[n];
            for (int i = 0; i < n; i++) {
                int len = random.nextInt(6); // 0 to 5
                str[i] = generateString(random, len);
            }
            l = -1;
            break;
        }
        case 7: // l = Integer.MAX_VALUE
        {
            int n = random.nextInt(5) + 1; // 1 to 5
            str = new String[n];
            for (int i = 0; i < n; i++) {
                int len = random.nextInt(6); // 0 to 5
                str[i] = generateString(random, len);
            }
            l = Integer.MAX_VALUE;
            break;
        }
        case 8: // l = 1, some strings of length 1
        {
            int n = random.nextInt(5) + 1; // 1 to 5
            str = new String[n];
            // At least one string of length 1
            int pos = random.nextInt(n);
            str[pos] = generateString(random, 1);
            for (int i = 0; i < n; i++) {
                if (i == pos) continue;
                int len = random.nextInt(6); // 0 to 5
                str[i] = generateString(random, len);
            }
            l = 1;
            break;
        }
        default: // case 9: multiple matches of same length
        {
            int n = random.nextInt(5) + 2; // 2 to 6 strings
            str = new String[n];
            int targetLen = random.nextInt(6); // 0 to 5
            // At least two strings of target length
            int pos1 = random.nextInt(n);
            int pos2;
            do {
                pos2 = random.nextInt(n);
            } while (pos2 == pos1);
            str[pos1] = generateString(random, targetLen);
            str[pos2] = generateString(random, targetLen);
            for (int i = 0; i < n; i++) {
                if (i == pos1 || i == pos2) continue;
                int len = random.nextInt(11); // 0 to 10
                str[i] = generateString(random, len);
            }
            l = targetLen;
            break;
        }
    }

    return new Object[]{str, l};
}

// Helper to generate a random string of exact length
private static String generateString(Random random, int length) {
    StringBuilder sb = new StringBuilder(length);
    for (int i = 0; i < length; i++) {
        // random lowercase letter
        char c = (char) ('a' + random.nextInt(26));
        sb.append(c);
    }
    return sb.toString();
}

