            for (int i = 0; i < wordCount; i++) {
                int wordLen = random.nextInt(15);
                for (int j = 0; j < wordLen; j++) {
                    sb.append((char)('a' + random.nextInt(26)));
                }
                if (i < wordCount - 1) {
                    sb.append(' ');
                }
            }
            str = sb.toString();
        }
    }

    return new Object[]{n, str};
}

