public static Object[] generateValidInput(Random random) {
    int maxLen = 10;
    String lower = "abcdefghijklmnopqrstuvwxyz";
    String upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    java.util.function.BiFunction<Integer, String, String> gen = (len, chars) -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < len; i++) {
            sb.append(chars.charAt(random.nextInt(chars.length())));
        }
        return sb.toString();
    };

    int mode = random.nextInt(5);
    String string1;
    String string2;

    if (mode == 0) {
        // Unequal lengths -> false branch
        int len1 = random.nextInt(maxLen + 1);
        int len2;
        do {
            len2 = random.nextInt(maxLen + 1);
        } while (len1 == len2);
        string1 = gen.apply(len1, lower);
        string2 = gen.apply(len2, lower);
    } else if (mode == 1) {
        // Same length but not a rotation: disjoint character sets
        int len = 1 + random.nextInt(maxLen);
        string1 = gen.apply(len, lower);
        string2 = gen.apply(len, upper);
    } else if (mode == 2) {
        // Genuine rotation -> true branch
        int len = random.nextInt(maxLen + 1);
        string1 = gen.apply(len, lower);
        if (len == 0) {
            string2 = "";
        } else {
            int rotation = random.nextInt(len);
            string2 = string1.substring(rotation) + string1.substring(0, rotation);
        }
    } else if (mode == 3) {
        // Explicit boundary cases
        int sub = random.nextInt(4);
        if (sub == 0) {
            string1 = "";
            string2 = "";
        } else if (sub == 1) {
            string1 = "a";
            string2 = "a";
        } else if (sub == 2) {
            string1 = "a";
            string2 = "b";
        } else {
            string1 = "abc";
            string2 = "abc";
        }
    } else {
        // Random equal-length strings, often not rotations
        int len = random.nextInt(maxLen + 1);
        string1 = gen.apply(len, lower);
        string2 = gen.apply(len, lower);
    }

    return new Object[]{string1, string2};
}

