        int type = random.nextInt(4);
        switch (type) {
            case 0: list.add(random.nextInt()); break;
            case 1: list.add(random.nextLong()); break;
            case 2: list.add(random.nextDouble()); break;
            case 3: list.add(random.nextBoolean()); break;
        }
    }
    // Occasionally include null element
    if (random.nextBoolean() && !list.isEmpty()) {
        list.set(random.nextInt(list.size()), null);
    }
    // Occasionally empty list
    if (random.nextInt(10) == 0) {
        list.clear();
    }
    // Generate string with placeholder variations
    String string;
    int stringChoice = random.nextInt(5);
    switch (stringChoice) {
        case 0: string = "temp{0}"; break;
        case 1: string = "python{0}"; break;
        case 2: string = "{0}"; break;
        case 3: string = "prefix-{0}-suffix"; break;
        default: string = "noPlaceholder"; break;
    }
    return new Object[]{list, string};
}

