public static Object[] generateValidInput(Random random) {
    String[] patterns;
    String text;

    // Decide case type
    int caseType = random.nextInt(8);
    switch (caseType) {
        case 0: // patterns = null
            patterns = null;
            text = randomString(random);
            break;
        case 1: // patterns empty array
            patterns = new String[0];
            text = randomString(random);
            break;
        case 2: // patterns with one element, text empty
            patterns = new String[]{randomStringOrNull(random)};
            text = "";
            break;
        case 3: // patterns with one element, text null
            patterns = new String[]{randomStringOrNull(random)};
            text = null;
            break;
        case 4: // patterns with multiple elements, some matching
            int n = random.nextInt(5) + 2; // 2..6 elements
            patterns = new String[n];
            // Generate a random text that will contain at least one pattern
            int matchIndex = random.nextInt(n);
            String matchingPattern = randomWord(random);
            patterns[matchIndex] = matchingPattern;
            for (int i = 0; i < n; i++) {
                if (i != matchIndex) {
                    patterns[i] = randomWord(random);
                }
            }
            // Text that contains the matching pattern
            text = randomPrefix(random) + matchingPattern + randomSuffix(random);
            break;
        case 5: // patterns array with null elements
            patterns = new String[]{null, randomStringOrNull(random), randomStringOrNull(random)};
            text = randomString(random);
            break;
        case 6: // patterns with empty strings, text random
            patterns = new String[]{"", randomStringOrNull(random), ""};
            text = randomString(random);
            break;
        case 7: // Both null or one null, one empty
            if (random.nextBoolean()) {
                patterns = null;
                text = null;
            } else {
                patterns = new String[0];
                text = null;
            }
            break;
        default:
            patterns = new String[]{randomStringOrNull(random)};
            text = randomString(random);
            break;
    }

    return new Object[]{patterns, text};
}

// Helper: generate a random string of length 0..10 using lowercase letters and spaces
private static String randomString(Random random) {
    int len = random.nextInt(11); // 0..10
    StringBuilder sb = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        // 50% chance of space, 50% chance of letter
        if (random.nextBoolean()) {
            sb.append(' ');
        } else {
            sb.append((char) ('a' + random.nextInt(26)));
        }
    }
    return sb.toString();
}

// Helper: sometimes return null, otherwise a random string
private static String randomStringOrNull(Random random) {
    if (random.nextDouble() < 0.2) {
        return null;
    }
    return randomString(random);
}

// Helper: generate a random word (no spaces) of length 1..5
private static String randomWord(Random random) {
    int len = random.nextInt(5) + 1;
    StringBuilder sb = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        sb.append((char) ('a' + random.nextInt(26)));
    }
    return sb.toString();
}

// Helper: random prefix (could be empty)
private static String randomPrefix(Random random) {
    if (random.nextBoolean()) {
        return "";
    }
    int len = random.nextInt(5);
    StringBuilder sb = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        sb.append((char) ('a' + random.nextInt(26)));
    }
    return sb.toString();
}

// Helper: random suffix (could be empty)
private static String randomSuffix(Random random) {
    if (random.nextBoolean()) {
        return "";
    }
    int len = random.nextInt(5);
    StringBuilder sb = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        sb.append((char) ('a' + random.nextInt(26)));
    }
    return sb.toString();
}

