full_code:
import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class GetLudic {

    public static int[] getLudic(int n) {
        int[] ludics = new int[n];
        int count = 0; // To keep track of numbers added

        for (int i = 1; i <= n; i++) {
            ludics[count++] = i;
        }

        int index = 1; // Start from the second element in the array
        while (index < count) {
            int first_ludic = ludics[index];
            int remove_index = index + first_ludic;

            while (remove_index < count) {
                System.arraycopy(ludics, remove_index + 1, ludics, remove_index, count - remove_index - 1);
                count--; // Decrease count as we've effectively removed an element
                remove_index += first_ludic - 1;
            }
            index += 1; // Move to the next ludic number
        }

        int[] result = Arrays.copyOf(ludics, count);
        return result;
    }
}

